const fmtChange=n=>n==null?"—":`${n>=0?"+":""}${Number(n).toFixed(1)}%`;
const ratio=(a,b)=>a!=null&&b>0?a/b:null;
const fmtRatio=n=>n==null?"—":n>=100?n.toFixed(0)+"×":n.toFixed(2)+"×";
